SELECT location, CASE WHEN budget >= 3658000 THEN 'high' WHEN budget >= 1657000 THEN 'mid' ELSE 'low' END AS budget_bucket, ROUND((100 * SUM(CASE WHEN location = 'Berlin' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_berlin, SUM(CASE WHEN location = 'London' THEN budget ELSE 0 END) AS london_budget, MAX(budget) - MIN(budget) AS budget_range FROM departments WHERE NOT ((location IN ('Chiang Mai', 'Tokyo', 'Bangkok') AND location IN ('Berlin', 'London', 'Tokyo')) OR location IN ('Chiang Mai', 'Singapore', 'New York')) GROUP BY location, CASE WHEN budget >= 3658000 THEN 'high' WHEN budget >= 1657000 THEN 'mid' ELSE 'low' END ORDER BY pct_berlin DESC
